import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readdirSync, readFileSync } from 'node:fs';
import { HERO_NAMES, heroName } from '../overlay/heroes.js';

/**
 * overlay/heroes.js is generated by scripts/vendor.mjs. The same drift that hit
 * tokens.css can hit it — a roster change leaving the map stale — so the
 * relationship between the names and the vendored icons is pinned here.
 */

test('every vendored icon has a name to fall back to', () => {
  // The icon is what shows; the name is what it says when it cannot. An icon
  // without a name would put `Hero 20` back on the broadcast.
  const ids = readdirSync('overlay/heroes')
    .filter(f => f.endsWith('.webp'))
    .map(f => Number(f.replace('.webp', '')));
  assert.ok(ids.length > 20, `only ${ids.length} icons found`);
  for (const id of ids) {
    assert.ok(HERO_NAMES[id], `heroes/${id}.webp has no name in HERO_NAMES`);
  }
});

test('the map covers more heroes than have icons', () => {
  // Deliberate: heroes shipping no small icon are the ones that need a name.
  const icons = readdirSync('overlay/heroes').filter(f => f.endsWith('.webp')).length;
  assert.ok(Object.keys(HERO_NAMES).length > icons,
    'heroes without a vendored icon must still be named');
});

test('heroName never returns a bare number, and refuses a non-id', () => {
  assert.equal(heroName(1), HERO_NAMES[1]);
  assert.match(heroName(999999), /^Hero 999999$/, 'an unknown id still reads as a label');
  for (const bad of [null, undefined, 'x', 1.5, {}]) {
    assert.equal(heroName(bad), null, `heroName(${JSON.stringify(bad)}) must be null`);
  }
});

test('the file is generated, and says so', () => {
  const src = readFileSync('overlay/heroes.js', 'utf8');
  assert.match(src, /GENERATED by scripts\/vendor\.mjs/,
    'a hand-edited name map is how this goes stale');
});
